class Solution {
    public int countPrimes(int n){
        boolean[] composite=new boolean[n];
        for(int p=2;(long)p*p<n;p++)if(!composite[p])for(int value=p*p;value<n;value+=p)composite[value]=true;
        int count=0;
        for(int value=2;value<n;value++)if(!composite[value])count++;
        return count;
    }
}

code.kotlin:
class Solution {
    fun countPrimes(n:Int):Int{
        val composite=BooleanArray(n);
        var p=2;
        while(p.toLong()*p<n){
            if(!composite[p]){
                var value=p*p;
                while(value<n){
                    composite[value]=true;
                    value+=p
                }
            };
            p++
        };
        var count=0;
        for(value in 2 until n)if(!composite[value])count++;
        return count
    }
}

code.cpp:
class Solution {
    public: int countPrimes(int n){
        vector<bool> composite(n);
        for(int p=2;(long long)p*p<n;++p)if(!composite[p])for(int value=p*p;value<n;value+=p)composite[value]=true;
        int count=0;
        for(int value=2;value<n;++value)if(!composite[value])++count;
        return count;
    }
};
